/// A piece of a set's data as a preset or a default holds it.
#[derive(Clone, Copy, Debug)]
pub enum Preset {
    Null,
    Flag(bool),
    Whole(i64),
    Text(&'static str),
    List(&'static [Preset]),
    Map(&'static [(&'static str, Preset)]),
}

/// How the instrument page shows one of a part's settings.
#[derive(Clone, Copy, Debug)]
pub enum SettingKind {
    Choice {
        choices: &'static [&'static str],
        names: &'static [&'static str],
    },
    Toggle,
    Number {
        lowest: i64,
        highest: i64,
        unit: &'static str,
        zero: Option<&'static str>,
    },
    SidTime {
        highest: i64,
        times: i64,
    },
    Gauge {
        lowest: i64,
        highest: i64,
        what: &'static str,
    },
}

